// ---- CLI argument parsing with clap ----
// Add to Cargo.toml:
// [dependencies]
// clap = { version = "4.0", features = ["derive"] }

use clap::{Parser, Subcommand, Args};

#[derive(Parser)]
#[command(name = "rust-cli")]
#[command(about = "A CLI tool built with Rust", long_about = None)]
struct Cli {
    /// Name of the file to process
    #[arg(short, long)]
    file: Option<String>,

    /// Number of times to repeat
    #[arg(short, long, default_value_t = 1)]
    count: u8,

    /// Enable verbose output
    #[arg(short, long)]
    verbose: bool,

    #[command(subcommand)]
    command: Option<Commands>,
}

#[derive(Subcommand)]
enum Commands {
    /// Greet a person
    Greet(GreetArgs),

    /// Process data
    Process(ProcessArgs),
}

#[derive(Args)]
struct GreetArgs {
    /// Name of the person to greet
    name: String,

    /// Title to use
    #[arg(short, long, default_value = "Hero")]
    title: String,
}

#[derive(Args)]
struct ProcessArgs {
    /// Input file path
    input: String,

    /// Output file path
    #[arg(short, long)]
    output: Option<String>,
}

fn main() {
    let cli = Cli::parse();

    // ---- Basic flags ----
    if let Some(file) = cli.file {
        println!("File: {}", file);
    }

    println!("Count: {}", cli.count);

    if cli.verbose {
        println!("Verbose mode enabled");
    }

    // ---- Subcommands ----
    match cli.command {
        Some(Commands::Greet(args)) => {
            println!("Hello, {} {}!", args.title, args.name);
        }
        Some(Commands::Process(args)) => {
            println!("Processing: {}", args.input);
            if let Some(output) = args.output {
                println!("Output to: {}", output);
            }
        }
        None => {
            println!("No command specified");
            println!("Use --help for usage information");
        }
    }
}

// ---- Usage examples ----
// cargo run -- --file data.txt
// cargo run -- --file data.txt --count 3 --verbose
// cargo run -- greet Alice --title "Queen"
// cargo run -- process input.csv --output output.csv

